import java.sql.*;
public class Ddl {
  static String[] STMTS = {
    "CREATE TABLE SYS_USER_SESSION (" +
      "ID NUMBER GENERATED BY DEFAULT AS IDENTITY NOT NULL, " +
      "SESSION_ID VARCHAR2(64) NOT NULL, " +
      "USER_ID VARCHAR2(64) NOT NULL, " +
      "USERNAME VARCHAR2(64), DISPLAY_NAME VARCHAR2(128), " +
      "TOKEN_HASH VARCHAR2(128) NOT NULL, " +
      "DEVICE_TYPE VARCHAR2(32) NOT NULL, " +
      "DEVICE_ID VARCHAR2(128), DEVICE_INFO VARCHAR2(500), " +
      "IP VARCHAR2(64), USER_AGENT CLOB, " +
      "LOGIN_TIME TIMESTAMP(6) NOT NULL, LAST_ACTIVE_TIME TIMESTAMP(6) NOT NULL, EXPIRE_TIME TIMESTAMP(6) NOT NULL, " +
      "REMEMBER_ME NUMBER(1) DEFAULT 0 NOT NULL CHECK (REMEMBER_ME IN (0,1)), " +
      "STATUS VARCHAR2(16) NOT NULL, " +
      "LOGOUT_TYPE VARCHAR2(32), LOGOUT_TIME TIMESTAMP(6), " +
      "REMARK VARCHAR2(500), " +
      "CREATE_BY VARCHAR2(64), CREATE_TIME TIMESTAMP(6) DEFAULT SYSTIMESTAMP NOT NULL, " +
      "UPDATE_BY VARCHAR2(64), UPDATE_TIME TIMESTAMP(6) DEFAULT SYSTIMESTAMP NOT NULL, " +
      "CONSTRAINT PK_SYS_USER_SESSION PRIMARY KEY (ID))",
    "CREATE UNIQUE INDEX UK_SYS_USER_SESSION_SESSION_ID ON SYS_USER_SESSION (SESSION_ID)",
    "CREATE INDEX IDX_SYS_USER_SESSION_USER_STATUS ON SYS_USER_SESSION (USER_ID, STATUS)",
    "CREATE INDEX IDX_SYS_USER_SESSION_EXPIRE_TIME ON SYS_USER_SESSION (EXPIRE_TIME)",
    "CREATE INDEX IDX_SYS_USER_SESSION_LAST_ACTIVE ON SYS_USER_SESSION (LAST_ACTIVE_TIME)",
    "CREATE INDEX IDX_SYS_USER_SESSION_USER_ACTIVE ON SYS_USER_SESSION (USER_ID, STATUS, LAST_ACTIVE_TIME)",
    "CREATE INDEX IDX_SYS_USER_SESSION_TOKEN_HASH ON SYS_USER_SESSION (TOKEN_HASH)",
    "ALTER TABLE SYS_USER_SESSION ADD CONSTRAINT CK_SYS_USER_SESSION_STATUS CHECK (STATUS IN ('ACTIVE','EXPIRED','LOGOUT','KICKED'))",
    "ALTER TABLE SYS_USER_SESSION ADD CONSTRAINT CK_SYS_USER_SESSION_DEVICE CHECK (DEVICE_TYPE IN ('PC','MOBILE','TABLET','MINI_PROGRAM','OTHER'))",
    "ALTER TABLE SYS_USER_SESSION ADD CONSTRAINT CK_SYS_USER_SESSION_TIME CHECK (EXPIRE_TIME >= LOGIN_TIME)",
    "ALTER TABLE SYS_USER_SESSION ADD CONSTRAINT CK_SYS_USER_SESSION_TERMINAL CHECK ((STATUS = 'ACTIVE' AND LOGOUT_TIME IS NULL) OR (STATUS <> 'ACTIVE' AND LOGOUT_TIME IS NOT NULL))",
    "CREATE TABLE SYS_USER_SESSION_LOG (" +
      "LOG_ID NUMBER GENERATED BY DEFAULT AS IDENTITY NOT NULL, " +
      "SESSION_ID VARCHAR2(64), " +
      "USER_ID VARCHAR2(64) NOT NULL, " +
      "USERNAME VARCHAR2(64), " +
      "ACTION_TYPE VARCHAR2(32) NOT NULL, " +
      "OPERATOR_ID VARCHAR2(64), OPERATOR_NAME VARCHAR2(64), " +
      "IP VARCHAR2(64), RESULT_CODE VARCHAR2(32), RESULT_DESC VARCHAR2(500), " +
      "OPERATE_TIME TIMESTAMP(6) DEFAULT SYSTIMESTAMP NOT NULL, " +
      "CONSTRAINT PK_SYS_USER_SESSION_LOG PRIMARY KEY (LOG_ID))",
    "CREATE INDEX IDX_SYS_SESSION_LOG_USER_TIME ON SYS_USER_SESSION_LOG (USER_ID, OPERATE_TIME)",
    "CREATE INDEX IDX_SYS_SESSION_LOG_SESSION ON SYS_USER_SESSION_LOG (SESSION_ID)",
    "ALTER TABLE SYS_USER_SESSION_LOG ADD CONSTRAINT CK_SYS_USER_SESSION_LOG_ACTION CHECK (ACTION_TYPE IN ('LOGIN','LOGOUT','KICK','REPLACED','OVER_LIMIT','EXPIRE_CLEAN'))"
  };
  public static void main(String[] a) throws Exception {
    Connection c = DriverManager.getConnection("jdbc:oracle:thin:@//172.16.253.180:1521/orcl","jddba","xingx888");
    int ok = 0, skip = 0, err = 0;
    for (String s : STMTS) {
      String name = s.length() > 60 ? s.substring(0, 60) : s;
      try { c.createStatement().execute(s); ok++; System.out.println("OK   : " + name); }
      catch (SQLException e) {
        if (e.getErrorCode() == 955 || e.getErrorCode() == 1422 || e.getErrorCode() == 2260 || e.getErrorCode() == 2261 || e.getErrorCode() == 2264) {
          skip++; System.out.println("SKIP : " + name + "  [" + e.getMessage().trim() + "]");
        } else { err++; System.out.println("ERR  : " + name + "  ORA-" + e.getErrorCode() + " " + e.getMessage().trim()); }
      }
    }
    System.out.println("RESULT ok=" + ok + " skip=" + skip + " err=" + err);
    c.close();
  }
}
